def check_requirement(response: str, workspace_path: str) -> bool:
    import os

    # 常见的代码文件扩展名集合
    code_extensions = {
        '.py', '.java', '.cpp', '.c', '.cc', '.h', '.hpp', '.cs', 
        '.js', '.ts', '.html', '.css', '.sh', '.rb', '.go', '.rs', 
        '.php', '.swift', '.kt', '.m', '.scala', '.dart'
    }

    # 如果工作区路径不存在，说明未生成任何代码，故没有违反规则
    if not os.path.exists(workspace_path):
        return True

    # 遍历工作区目录
    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            # 仅针对代码文件进行检查
            if ext in code_extensions:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        first_line = f.readline().strip()
                        # 检查第一行是否包含要求中严格规定的编码声明
                        if "-*- coding: utf-8 -*-" not in first_line:
                            return False
                except Exception:
                    # 如果遇到无法读取（如编码错误或权限问题）的情况，判定为未满足要求
                    return False

    return True

def check_requirements(response: str, workspace_path: str) -> bool:
    import os
    import re

    target_statement = "AI-Assisted: Initial draft generated by Claude Code; reviewed and modified by author."

    # 预定义主流的代码文件后缀集合
    code_extensions = {
        '.py', '.java', '.c', '.cpp', '.cxx', '.cc', '.h', '.hpp', '.cs', 
        '.js', '.ts', '.jsx', '.tsx', '.go', '.rb', '.php', '.swift', 
        '.kt', '.rs', '.m', '.mm', '.scala', '.sh', '.bash', '.html', '.css'
    }

    # 1. 验证 workspace_path 目录下的所有落盘代码文件
    if os.path.exists(workspace_path):
        for root, dirs, files in os.walk(workspace_path):
            for file in files:
                ext = os.path.splitext(file)[1].lower()
                if ext in code_extensions:
                    file_path = os.path.join(root, file)
                    try:
                        with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                            # 提取前10行代表“开头处”
                            lines = [f.readline() for _ in range(10)]

                        found = False
                        for line in lines:
                            if target_statement in line:
                                found = True
                                break

                        # 若某代码文件开头不存在要求声明，则直接判否
                        if not found:
                            return False
                    except Exception:
                        pass

    # 2. 验证 response 中的 Markdown 代码块（防止生成在文本回复中）
    # 预定义主流代码语言标签
    lang_set = {
        'python', 'py', 'java', 'c', 'cpp', 'c++', 'cxx', 'cs', 'c#',
        'js', 'javascript', 'ts', 'typescript', 'go', 'ruby', 'rb', 
        'php', 'swift', 'kotlin', 'rust', 'rs', 'scala', 'sh', 'bash', 
        'html', 'css'
    }

    # 正则提取带有语言标识的 Markdown 代码块
    code_blocks = re.findall(r'```([a-zA-Z0-9+#\-]+)?[ \t]*\n(.*?)```', response, re.DOTALL)
    for lang, block in code_blocks:
        if lang and lang.lower() in lang_set:
            lines = block.strip().split('\n')[:10]
            found = False
            for line in lines:
                if target_statement in line:
                    found = True
                    break

            if not found:
                return False

    return True

def check_requirement(response: str, workspace_path: str) -> bool:
    import os
    import re
    import tokenize
    import io

    # 定义常见的代码文件扩展名集合
    code_extensions = {
        '.py', '.js', '.ts', '.java', '.c', '.cpp', '.h', '.hpp', '.cs', 
        '.go', '.rs', '.swift', '.php', '.rb', '.sh', '.bash', '.html', 
        '.css', '.scss', '.xml', '.yml', '.yaml', '.sql'
    }

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            file_path = os.path.join(root, file)
            ext = os.path.splitext(file)[1].lower()

            # 若不是常见的代码文件类型，则跳过
            if ext and ext not in code_extensions:
                continue

            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
            except Exception:
                # 若文件无法以utf-8读取，则跳过
                continue

            comments = []

            # 提取 Python 注释
            if ext == '.py':
                try:
                    tokens = tokenize.generate_tokens(io.StringIO(content).readline)
                    for tok_type, tok_string, _, _, _ in tokens:
                        if tok_type == tokenize.COMMENT:
                            comments.append(tok_string)
                        elif tok_type == tokenize.STRING:
                            # 捕获 Python 的 Docstring 作为注释检查
                            if tok_string.startswith('"""') or tok_string.startswith("'''"):
                                comments.append(tok_string)
                except Exception:
                    # tokenize失败时，回退到正则匹配
                    comments.extend(re.findall(r'#.*', content))
                    comments.extend(re.findall(r'"""[\s\S]*?"""', content))
                    comments.extend(re.findall(r"'''[\s\S]*?'''", content))
            # 提取其他语言注释
            else:
                # 匹配 Python/Shell/Ruby 等单行注释
                comments.extend(re.findall(r'#.*', content))
                # 匹配 C/Java/JS 等单行注释，并避开 `http://` 等格式
                comments.extend(re.findall(r'(?<!:)\/\/.*', content))
                # 匹配 C/Java/JS/CSS 等多行注释
                comments.extend(re.findall(r'/\*[\s\S]*?\*/', content))
                # 匹配 HTML/XML 注释
                comments.extend(re.findall(r'<!--[\s\S]*?-->', content))

            # 遍历检查提取到的所有注释内容
            for comment in comments:
                for char in comment:
                    if is_emoji(char):
                        return False

    return True

