def check_requirement(response: str, workspace_path: str) -> bool:
    import os

    # 辅助函数：判断一段文本中是否包含违规的第二人称称呼“你”或“您”
    def contains_second_person_pronoun(text: str) -> bool:
        if not text:
            return False
        # 将带有“你”但通常不作为人称代词使用的常见特例词汇剔除，避免产生误判
        clean_text = text.replace("迷你", "").replace("迪士尼", "")
        # 检查剔除后是否依然包含“你”或“您”
        if "你" in clean_text or "您" in clean_text:
            return True
        return False

    # 1. 检查 AI 助手的最后一轮回复文本中是否违规使用了“你”或“您”
    if contains_second_person_pronoun(response):
        return False

    # 2. 检查工作区生成的代码文件与进度日志文件是否违规
    if os.path.exists(workspace_path) and os.path.isdir(workspace_path):
        # 根据用户指令中提到的 Web 三剑客和进度日志推断目标文件类型
        target_extensions = ('.html', '.css', '.js', '.md', '.txt', '.json')
        for root, dirs, files in os.walk(workspace_path):
            for file_name in files:
                if file_name.endswith(target_extensions):
                    file_path = os.path.join(root, file_name)
                    try:
                        with open(file_path, 'r', encoding='utf-8') as f:
                            content = f.read()
                            if contains_second_person_pronoun(content):
                                return False
                    except Exception:
                        # 对于无法以 utf-8 读取或发生其他 IO 异常的文件，直接跳过
                        continue

    # 如果所有被检查的内容里均未出现“你”或“您”，则认为满足了给定要求
    return True

