def check_indentation(response: str, workspace_path: str) -> bool:
    import os

    valid_extensions = {'.html', '.css', '.js'}
    tab_lines = 0
    space_lines = 0
    indent_counts = {}
    has_code_files = False

    if not os.path.exists(workspace_path):
        return False

    # 遍历工作区，查找代码文件
    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            if any(file.endswith(ext) for ext in valid_extensions):
                has_code_files = True
                file_path = os.path.join(root, file)

                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        lines = f.readlines()
                except Exception:
                    continue

                # 分析每一行的缩进
                for line in lines:
                    if not line.strip():  # 跳过空行
                        continue

                    stripped_line = line.lstrip()
                    if stripped_line == line:  # 跳过没有缩进的顶头行
                        continue

                    indent_str = line[:len(line)-len(stripped_line)]

                    # 检查是否包含制表符
                    if '\t' in indent_str:
                        tab_lines += 1
                    else:
                        spaces = len(indent_str)
                        indent_counts[spaces] = indent_counts.get(spaces, 0) + 1
                        space_lines += 1

    # 如果没有找到任何相关的代码文件，无法判断是否满足，按不通过处理
    if not has_code_files:
        return False

    even_spaces = 0
    mod4_spaces = 0

    # 统计偶数空格缩进和4的倍数空格缩进的情况
    for spaces, count in indent_counts.items():
        if spaces % 2 == 0:
            even_spaces += count
            if spaces % 4 == 0:
                mod4_spaces += count

    # 如果用 Tab 缩进的行数比用空格缩进的行数还多，判定不通过
    if tab_lines > space_lines:
        return False

    # 如果代码完全没有偶数空格缩进（可能均无缩进或格式异常），判定不通过
    if even_spaces == 0:
        return False

    # 判断4的倍数空格是否在偶数空格缩进中占据主导地位（阈值设为 80%）
    if mod4_spaces / even_spaces >= 0.8:
        return True

    return False

