def verify(response: str, workspace_path: str) -> bool:
    """
    检查代码项目中的各个代码文件，判断它们的注释内容中是否含有emoji。
    如果在任何一个代码文件的注释里发现了emoji，则返回False，否则返回True。
    """
    # 常用代码文件后缀分类
    html_exts = {'.html', '.htm'}
    c_style_exts = {'.js', '.css', '.ts', '.jsx', '.tsx', '.java', '.c', '.cpp', '.cs', '.go', '.swift', '.kt', '.php'}
    hash_exts = {'.py', '.rb', '.sh', '.yaml', '.yml'}

    # 注释的正则表达式提取
    html_comment_re = re.compile(r'<!--[\s\S]*?-->')
    multiline_comment_re = re.compile(r'/\*[\s\S]*?\*/')
    # 使用负向后行断言 (?<!:) 避免匹配到 http:// 或 https:// 
    single_line_comment_re = re.compile(r'(?<!:)//[^\r\n]*')
    hash_comment_re = re.compile(r'#[^\r\n]*')

    # 用于移除字符串字面量（避免字符串内部被误解析为注释）
    string_re = re.compile(r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|`(?:\\.|[^`\\])*`')

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()

            # 仅处理常见的代码文件，跳过Markdown等文档文件
            if ext not in html_exts and ext not in c_style_exts and ext not in hash_exts:
                continue

            file_path = os.path.join(root, file)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
            except Exception:
                continue

            # 首先剔除字符串字面量，防止误匹配
            content_no_strings = string_re.sub('', content)
            comments = []

            # 根据文件类型收集可能的注释区块
            if ext in html_exts:
                comments.extend(html_comment_re.findall(content_no_strings))
                comments.extend(multiline_comment_re.findall(content_no_strings))
                comments.extend(single_line_comment_re.findall(content_no_strings))

            if ext in c_style_exts:
                comments.extend(multiline_comment_re.findall(content_no_strings))
                comments.extend(single_line_comment_re.findall(content_no_strings))
                if ext == '.php':
                    comments.extend(html_comment_re.findall(content_no_strings))
                    comments.extend(hash_comment_re.findall(content_no_strings))

            if ext in hash_exts:
                comments.extend(hash_comment_re.findall(content_no_strings))

            # 遍历所有被提取出来的注释文本，判断是否含有emoji
            for comment in comments:
                for char in comment:
                    if is_emoji(char):
                        return False

    return True

