    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in code_extensions:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        lines = f.readlines()
                except Exception:
                    # 如果由于编码等问题无法读取，则跳过
                    continue

                code_files_found += 1
                file_indents = []

                for line in lines:
                    # 滤除结尾换行和空白，若当前行为空则跳过
                    if not line.strip():
                        continue

                    # 匹配行首前导空白字符
                    match = re.match(r'^([ \t]+)', line)
                    if match:
                        whitespace = match.group(1)

                        # 过滤掉以星号开头用于对齐的多行注释内部行 (如 JSDoc / CSS 注释)
                        if re.match(r'^[ \t]+\*(\s|$)', line):
                            continue

                        # 只要发现存在制表符缩进，即违背了“采用空格”的规则
                        if '\t' in whitespace:
                            return False

                        # 记录具体的空格缩进数
                        file_indents.append(len(whitespace))

                # 对文件的缩进情况进行统计分析
                if file_indents:
                    # 统计缩进量为4的倍数（即符合4个空格缩进层级）的代码行数
                    count_multiples_of_4 = sum(1 for x in file_indents if x % 4 == 0)
                    total_indents = len(file_indents)

                    if total_indents >= 5:
                        # 对于超过一定行数的文件，若4的倍数缩进行占比小于60%，很可能是2空格或其他缩进
                        if count_multiples_of_4 < total_indents * 0.6:
                            return False
                    else:
                        # 文件内缩进行较少时（如极短的代码文件），若存在偶数且无4的倍数缩进（如2，6），判定失败
                        if count_multiples_of_4 == 0 and sum(1 for x in file_indents if x % 2 == 0) > 0:
                            return False

    # 若工作区内连一个合规类型的代码文件都没有，则无法验证成功
    if code_files_found == 0:
        return False

    return True

