    code_comment_pattern = re.compile(
        r'"(?:\\.|[^"\\])*"'            # 双引号字符串
        r'|\'(?:\\.|[^\'\\])*\''        # 单引号字符串
        r'|`(?:\\.|[^`\\])*`'           # 反引号字符串
        r'|(/\*[\s\S]*?\*/|//.*|#.*)'   # 块注释或行注释
    )

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            # 过滤前端及常见的代码类型
            if ext not in ['.html', '.htm', '.js', '.css', '.py', '.ts', '.jsx', '.tsx']:
                continue

            file_path = os.path.join(root, file)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
            except Exception:
                continue

            comments = []

            if ext in ['.html', '.htm']:
                # 收集 HTML 自身的原生注释
                comments.extend(html_comment_pattern.findall(content))

                # 收集内嵌 JS / CSS 中的代码注释
                for match in script_style_pattern.finditer(content):
                    inner_content = match.group(2)
                    for m in code_comment_pattern.finditer(inner_content):
                        if m.group(1):
                            comments.append(m.group(1))
            else:
                # 直接收集纯代码文件中的注释
                for m in code_comment_pattern.finditer(content):
                    if m.group(1):
                        comments.append(m.group(1))

            # 遍历所有提取出来的注释文本片段
            for comment in comments:
                for char in comment:
                    # 使用人类专家提供的 is_emoji 函数判断该字符
                    if is_emoji(char):
                        return False  # 如果在任何一处注释中发现 emoji，判定为未满足要求，返回 False

    return True  # 所有的代码文件注释均无 emoji，满足给定要求

import os
from collections import Counter

def verify(response: str, workspace_path: str) -> bool:
    # 定义该项目相关的代码文件后缀
    code_extensions = {'.html', '.css', '.js'}
    code_files = []

    # 遍历获取工作区下的全部代码文件
    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            if os.path.splitext(file)[1].lower() in code_extensions:
                code_files.append(os.path.join(root, file))

    # 如果没找到任何代码文件，则无法验证是否满足要求
    if not code_files:
        return False

    for filepath in code_files:
        with open(filepath, 'r', encoding='utf-8') as f:
            try:
                lines = f.readlines()
            except UnicodeDecodeError:
                # 忽略编码异常的非文本文件
                continue

        indents = []
        for line in lines:
            # 过滤空行
            if not line.strip():
                continue

            stripped = line.lstrip()
            # 截取前导空白字符
            indent_str = line[:len(line) - len(stripped)]

            # 如果缩进中存在制表符（Tab），直接判定失败
            if '\t' in indent_str:
                return False

            # 忽略部分可能为了对齐而出现异常缩进的注释格式
            if stripped.startswith('*') or stripped.startswith('/*') or stripped.startswith('<!--'):
                continue

            indents.append(len(indent_str))

        # 计算相邻行的缩进步长
        steps = []
        for i in range(1, len(indents)):
            diff = abs(indents[i] - indents[i-1])
            # 仅在缩进发生变化时记录步长
            if diff > 0:
                steps.append(diff)

        # 分析主导的缩进风格
        if steps:
            c = Counter(steps)
            # 如果 2 空格或 3 空格的缩进变化频率高于 4 空格，说明不符合 4 空格缩进的要求
            if c[2] > c[4] or c[3] > c[4]:
                return False

    return True

import os
import re

def check_requirements(response: str, workspace_path: str) -> bool:
    # 辅助函数：替换字符串内容和URL，防止内部碰巧出现的 '//' 或 '/*' 被误识别为注释
    def remove_strings_and_urls(text: str) -> str:
        # 替换常见 URL 协议头，防止 http:// 中的 // 被识别为注释
        text = text.replace('http://', 'http__').replace('https://', 'https__')
        # 将双引号、单引号、反引号内的字符串内容替换为下划线 '_'
        text = re.sub(r'"[^"\\]*(?:\\.[^"\\]*)*"', '_', text)
        text = re.sub(r"'[^'\\]*(?:\\.[^'\\]*)*'", '_', text)
        text = re.sub(r'`[^`\\]*(?:\\.[^`\\]*)*`', '_', text)
        return text

    # 核心检查逻辑：验证一组代码行是否符合要求
    def check_lines(lines: list, ext_or_lang: str) -> bool:
        # 根据文件扩展名或语言类型分配可能出现的合法注释符
        if ext_or_lang in ['.js', '.ts', '.jsx', '.tsx', 'js', 'javascript', 'ts', 'typescript']:
            tokens = ['//', '/*']
        elif ext_or_lang in ['.css', 'css']:
            tokens = ['/*']
        elif ext_or_lang in ['.html', '.htm', 'html', 'htm']:
            # HTML 文件中可能内嵌 JS 和 CSS，所以放宽注释符校验
            tokens = ['<!--', '//', '/*']
        elif ext_or_lang in ['.py', 'python']:
            tokens = ['#']
        else:
            tokens = ['//', '/*', '<!--', '#']

        for line in lines:
            stripped = line.strip()
            # 忽略纯空行，空行不属于“代码行”范畴
            if not stripped:
                continue

            # 1. 检查是否为独立注释行（注释写在代码行之上或之下）
            is_standalone = False
            for token in tokens:
                if stripped.startswith(token):
                    is_standalone = True
                    break

            if is_standalone:
                return False # 发现独立注释行，不符合“不允许写在代码行之上或之下”

            # 2. 检查是否有追加注释（每行代码都必须有注释）
            line_no_str = remove_strings_and_urls(line)
            has_comment = False
            for token in tokens:
                if token in line_no_str:
                    has_comment = True
                    break

            if not has_comment:
                return False # 发现没有注释的代码行，不符合“每行代码都要求写注释”

        return True

    # 1. 优先扫描工作区中的代码文件
    code_extensions = ['.html', '.htm', '.js', '.css', '.ts', '.jsx', '.tsx', '.py']
    files_checked = 0

    if os.path.exists(workspace_path):
        for root, dirs, files in os.walk(workspace_path):
            for file in files:
                ext = os.path.splitext(file)[1].lower()
                if ext in code_extensions:
                    filepath = os.path.join(root, file)
                    try:
                        with open(filepath, 'r', encoding='utf-8') as f:
                            lines = f.readlines()
                        if not check_lines(lines, ext):
                            return False
                        files_checked += 1
                    except Exception:
                        pass

    if files_checked > 0:
        return True

    # 2. 如果工作区未找到文件，作为回退方案，检查 response 中的 Markdown 代码块
    blocks = re.findall(r'```(.*?)\n(.*?)```', response, re.DOTALL)
    if not blocks:
        return False # 未发现任何代码

    for lang, code in blocks:
        lang = lang.lower().strip()
        if not lang:
            lang = 'txt'
        if not check_lines(code.split('\n'), lang):
            return False

    return True
